// The modern, decoupled approach using Runnable
public class TaskProcessor {
    public void execute() {
        Runnable task = () -> System.out.println("Executing in: " + Thread.currentThread().getName());

        // Decoupled from the execution strategy
        ExecutorService executor = Executors.newFixedThreadPool(4);
        executor.submit(task);
        executor.shutdown();
    }
}
